+        listingRepository.save(listing);
+        return toDetailResponse(listing, List.of(), null);
+    }
+
+    @Transactional
+    public ListingDetailResponse updateListing(UUID listingId, UpdateListingRequest request, JwtUserPrincipal principal) {
