+        List<BenefitPackage> tierBenefits = benefitPackageRepository.findByTier_Id(membership.getTier().getId());
+
+        BigDecimal totalAmount = BigDecimal.ZERO;
+        BigDecimal discountAmount = BigDecimal.ZERO;
