+            OrderItem item = new OrderItem();
+            item.setId(UUID.randomUUID());
+            item.setOrder(order);
+            item.setListing(draft.listing());
+            item.setQuantity(draft.quantity());
+            item.setUnitPrice(draft.listing().getPrice());
+            item.setAppliedBenefit(draft.appliedBenefit());
