+    return apiClient.post(`/appeals/${appealId}/final-review`, payload);
+  },
+  async download(appealId, evidenceId) {
+    const response = await apiClient.get(`/appeals/${appealId}/evidence/${evidenceId}/download`, {
+      responseType: "blob",
+      skipEnvelope: true
+    });
+    return response;
+  }
+};
