    try {
      const updated = await ticketService.resolve(ticketId, { closure_code: closureCode, closure_notes: closureNotes });
      setTickets((prev) => prev.map((ticket) => (ticket.id === ticketId ? updated : ticket)));
      showToast("Ticket resolved", "success");
    } catch (error) {
      showToast(error?.message || "Resolve failed", "error");
    }
  };

  const reviewAppeal = async (appealId, decision) => {
    const decisionNotes = window.prompt("Decision notes:", "Reviewed by moderator");
    if (!decisionNotes) {
      return;
    }

    try {
      const updated = await appealService.review(appealId, { decision, decision_notes: decisionNotes });
      const flat = updated.appeal || updated;
      setAppeals((prev) => prev.map((appeal) => (appeal.id === appealId ? flat : appeal)));
      setSelectedAppeal(updated);
      showToast("Appeal reviewed", "success");
    } catch (error) {
      showToast(error?.message || "Appeal review failed", "error");
    }
  };

  return (
    <div className="page-grid">
      <Card>
        <h2>Ticket Queue</h2>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Type</th>
                <th>Severity</th>
                <th>Status</th>
                <th>Assigned</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {tickets.map((ticket) => (
                <tr key={ticket.id} className={ticket.status === "ESCALATED" ? "row-highlight" : ""}>
                  <td>{ticket.id.slice(0, 8)}...</td>
                  <td>{ticket.type}</td>
                  <td>{ticket.severity}</td>
                  <td>
                    <StatusBadge value={ticket.status} />
                  </td>
                  <td>{ticket.assigned_to_name || "Unassigned"}</td>
                  <td className="actions-row">
                    <Button variant="ghost" onClick={() => setSelectedTicket(ticket)}>
                      Open
                    </Button>
                    <Button variant="secondary" onClick={() => acknowledge(ticket.id)}>
                      Acknowledge
                    </Button>
                    <Button onClick={() => resolveTicket(ticket.id)}>Resolve</Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      <Card>
        <h2>Appeal Review Panel</h2>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Ticket</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {appeals.map((appeal) => (
                <tr key={appeal.id}>
                  <td>{appeal.id.slice(0, 8)}...</td>
                  <td>{appeal.ticket_id?.slice(0, 8)}...</td>
                  <td>
                    <StatusBadge value={appeal.status} />
                  </td>
                  <td className="actions-row">
                    <Button variant="ghost" onClick={async () => setSelectedAppeal(await appealService.detail(appeal.id))}>
                      View
                    </Button>
                    <Button variant="secondary" onClick={() => reviewAppeal(appeal.id, "APPROVED")}>Approve</Button>
                    <Button variant="danger" onClick={() => reviewAppeal(appeal.id, "DENIED")}>Deny</Button>
                    <Button onClick={() => reviewAppeal(appeal.id, "ESCALATED_TO_ADMIN")}>Escalate</Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {selectedAppeal?.appeal && (
          <div className="detail-mini-panel">
            <h4>Appeal {selectedAppeal.appeal.id.slice(0, 8)}...</h4>
            <p>{selectedAppeal.appeal.reason}</p>
            <p>
              Evidence files: {selectedAppeal.evidence?.length || 0} ┬╖ Last update {formatDateTime(selectedAppeal.appeal.created_at)}
            </p>
          </div>
        )}
      </Card>

      <Card>
        <h2>Risk Dashboard</h2>
        {risk ? (
          <div className="risk-grid">
            <article className="metric-card">
              <h4>Open Tickets</h4>
              <p>
                LOW {risk.open_tickets_low} ┬╖ MEDIUM {risk.open_tickets_medium} ┬╖ HIGH {risk.open_tickets_high}
              </p>
            </article>
            <article className="metric-card">
              <h4>Avg Resolution</h4>
              <p>{risk.avg_resolution_hours} hours</p>
            </article>
            <article className="metric-card">
              <h4>Escalation Rate</h4>
              <p>{risk.escalation_rate_percent}%</p>
            </article>
            <article className="metric-card">
              <h4>Active Flags</h4>
              <p>{risk.active_risk_flags}</p>
            </article>
            <article className="metric-card full-width">
              <h4>Top Flagged Sellers</h4>
              <ul className="plain-list">
                {(risk.top_flagged_sellers || []).map((row) => (
                  <li key={row.entity_id}>
                    {row.display_name}: {row.flag_type} ({row.incident_count})
                  </li>
                ))}
              </ul>
            </article>
            <article className="metric-card full-width">
              <h4>Top Flagged Members</h4>
              <ul className="plain-list">
                {(risk.top_flagged_members || []).map((row) => (
                  <li key={row.entity_id}>
                    {row.display_name}: {row.flag_type} ({row.incident_count})
                  </li>
                ))}
              </ul>
            </article>
          </div>
        ) : (
          <p>Loading risk dashboard...</p>
        )}
      </Card>

      {selectedTicket && (
        <Card>
          <h2>Escalation Inbox Detail</h2>
          <p>{selectedTicket.description}</p>
          <p>
            SLA Ack: {formatDateTime(selectedTicket.sla_acknowledge_by)} ┬╖ SLA Resolve: {formatDateTime(selectedTicket.sla_resolve_by)}
          </p>
        </Card>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { auditService, riskService, tierService, userService } from "../api";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { EmptyState } from "../components/EmptyState";
import { StatusBadge } from "../components/StatusBadge";
import { useToast } from "../components/ToastProvider";
import { formatDateTime } from "../utils/formatting";

export default function AdminPanelPage() {
  const { showToast } = useToast();
  const [users, setUsers] = useState([]);
  const [tiers, setTiers] = useState([]);
  const [benefits, setBenefits] = useState([]);
  const [auditLogs, setAuditLogs] = useState([]);
  const [risk, setRisk] = useState(null);
  const [auditFilter, setAuditFilter] = useState({ entityType: "", action: "", from: "", to: "" });

  useEffect(() => {
    Promise.allSettled([
      userService.list({ page: 0, pageSize: 50 }),
      tierService.listTiers(),
      tierService.listBenefits({}),
      auditService.list({ page: 0, pageSize: 50 }),
      riskService.dashboard()
    ]).then((results) => {
      const [usersRes, tiersRes, benefitsRes, auditRes, riskRes] = results;
      setUsers(usersRes.status === "fulfilled" ? usersRes.value || [] : []);
      setTiers(tiersRes.status === "fulfilled" ? tiersRes.value || [] : []);
      setBenefits(benefitsRes.status === "fulfilled" ? benefitsRes.value || [] : []);
      setAuditLogs(auditRes.status === "fulfilled" ? auditRes.value || [] : []);
      setRisk(riskRes.status === "fulfilled" ? riskRes.value : null);

      if (results.some((result) => result.status === "rejected")) {
        showToast("Some admin datasets are unavailable yet in backend.", "warn");
      }
    });
  }, [showToast]);

  const filteredAudit = auditLogs.filter((row) => {
    if (auditFilter.entityType && row.entity_type !== auditFilter.entityType) return false;
    if (auditFilter.action && row.action !== auditFilter.action) return false;
    if (auditFilter.from && new Date(row.created_at) < new Date(auditFilter.from)) return false;
    if (auditFilter.to && new Date(row.created_at) > new Date(auditFilter.to)) return false;
    return true;
  });

  return (
    <div className="page-grid">
      <Card>
        <h2>User Management</h2>
        {users.length === 0 ? (
          <EmptyState title="No user admin endpoint data" message="User management API can be wired when endpoint is exposed." />
        ) : (
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {users.map((user) => (
                  <tr key={user.id}>
                    <td>{user.email}</td>
                    <td>{user.role}</td>
                    <td>
                      <StatusBadge value={user.status} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <Card>
        <h2>Tier & Benefit Configuration</h2>
        <div className="two-col">
          <article>
            <h3>Tiers</h3>
            <ul className="plain-list">
              {tiers.map((tier) => (
                <li key={tier.id}>
                  {tier.name} ({tier.rank}) ΓÇö {tier.spend_threshold_min} to {tier.spend_threshold_max || "Γê₧"}
                </li>
              ))}
            </ul>
          </article>
          <article>
            <h3>Benefits</h3>
            <ul className="plain-list">
              {benefits.map((benefit) => (
                <li key={benefit.id}>
                  {benefit.name} ┬╖ {benefit.type} ┬╖ priority {benefit.priority}
                </li>
              ))}
            </ul>
          </article>
        </div>
      </Card>

      <Card>
        <h2>Audit Log Viewer</h2>
        <div className="filters-grid">
          <label>
            Entity Type
            <input
              value={auditFilter.entityType}
              onChange={(e) => setAuditFilter((prev) => ({ ...prev, entityType: e.target.value }))}
            />
          </label>
          <label>
            Action
            <input value={auditFilter.action} onChange={(e) => setAuditFilter((prev) => ({ ...prev, action: e.target.value }))} />
          </label>
          <label>
            From
            <input type="date" value={auditFilter.from} onChange={(e) => setAuditFilter((prev) => ({ ...prev, from: e.target.value }))} />
          </label>
          <label>
            To
            <input type="date" value={auditFilter.to} onChange={(e) => setAuditFilter((prev) => ({ ...prev, to: e.target.value }))} />
          </label>
        </div>
        {filteredAudit.length === 0 ? (
          <EmptyState title="No audit entries" message="No rows match your filter." />
        ) : (
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Time</th>
                  <th>Entity</th>
                  <th>Action</th>
                  <th>Changes</th>
                </tr>
              </thead>
              <tbody>
                {filteredAudit.map((row) => (
                  <tr key={row.id}>
                    <td>{formatDateTime(row.created_at)}</td>
                    <td>
                      {row.entity_type} ┬╖ {row.entity_id}
                    </td>
                    <td>{row.action}</td>
                    <td>
                      <pre className="json-viewer">{JSON.stringify(row.changes, null, 2)}</pre>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <Card>
        <h2>Analytics Dashboard</h2>
        {risk ? (
          <div className="analytics-grid">
            <article className="metric-card">
              <h4>Ticket Trends</h4>
              <p>
                LOW: {risk.open_tickets_low} ┬╖ MEDIUM: {risk.open_tickets_medium} ┬╖ HIGH: {risk.open_tickets_high}
              </p>
            </article>
            <article className="metric-card">
              <h4>Risk Flags Over Time</h4>
              <p>Active risk flags: {risk.active_risk_flags}</p>
            </article>
            <article className="metric-card full-width">
              <h4>Escalation Performance</h4>
              <p>
                Escalation Rate: {risk.escalation_rate_percent}% ┬╖ Avg resolution: {risk.avg_resolution_hours} hours
              </p>
            </article>
          </div>
        ) : (
          <p>Loading analytics...</p>
        )}
      </Card>
    </div>
  );
}

