:root {
  --bg: #0f172a;
  --bg-soft: #111c34;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --teal: #14b8a6;
  --amber: #f59e0b;
  --danger: #ef4444;
  --glass: rgba(255, 255, 255, 0.07);
  --glass-border: rgba(255, 255, 255, 0.14);
  --radius: 18px;
  --shadow-lg: 0 24px 55px rgba(2, 6, 23, 0.48);
  --shadow-md: 0 12px 28px rgba(2, 6, 23, 0.32);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: "Inter", sans-serif;
  color: var(--text);
