        if (!(reporter || assigned)) {
            throw new ApiException(HttpStatus.FORBIDDEN, "FORBIDDEN", "You cannot add a follow-up to this ticket");
        }
    }

    private void validateTransition(TicketStatus current, TicketStatus target) {
        if (current == target) {
